const TEACHING = "Under Pressure (Pack 1, level L4, version 1.1.0)\nPromise: The decisions you make slowly and correctly become the ones you make instantly.\n\n## Match Speed — Under Pressure\nSame plays. Three seconds. You already know the right call — now make it before you've finished thinking.\n\nEverything in this pack you've seen before. The difference is the clock: set the pressure to Match speed and the decision has to arrive while the picture is still moving. Use Slow and Replay as much as you like between attempts — the goal is recognition, not reaction. When you can get seven of eight defending plays and five of six distribution plays right at Match speed, you've turned knowledge into instinct.\n## On the Pitch — On the pitch\nMatch speed on the simulator means nothing until it shows on a Saturday. This pack is completed by matches, not by clicks.\n\nMatch speed on the simulator means nothing until it shows on a Saturday. This pack is completed by matches, not by clicks.\nCheck in after each session or match — a date, did it happen (yes, partly, no — all honest answers), and what you noticed. The record is yours. Nobody is checking; the point is that you are.\n\nWhy this pack can't be finished indoors: Reading, deciding and organising are habits, and habits are built on grass. The lessons and the simulator show you what good looks like; only matches and sessions make it yours. Completing a pack means it has shown up in your game — that is the whole point.";
const CLIENT = "Visuals on the site (client-only; decisions made there arrive as events in the shared document, not through a tool):\n- simulator set \"defend\" (shared with own-the-box/defend) → #s/under-pressure/pressure\n- simulator set \"distribute\" (shared with own-the-box/distribute) → #s/under-pressure/pressure";
const FIELD = "Field tasks (#s/under-pressure/on-the-pitch/field-under-pressure). Check-ins are honest self-reports; no proof, no policing.\n- no-hesitation (do, match): For a whole match, count your hesitations — any moment you started one decision and switched. Zero is the target; honesty is the point.\n  why: The only truly wrong decision is the half one. Pros are not faster thinkers; they commit earlier.\n  ask: How many? What was happening each time?\n- reviewed-goals (notice, match): For every goal or big chance against you, be able to say within a minute where it came from and what call or decision could have stopped it.\n  why: A conceded goal is information. This turns a bad moment into a better next one, in real time.\n  ask: List them: where from, what would have stopped it.\n- quiet-match (notice, match): After the match, count the chances you PREVENTED with a call or a position — the shots that never came. Those are your real saves now.\n  why: At this level keepers are judged by the quiet matches they create, not the saves they make.\n  ask: What did you prevent? Who did you move?";

export const checkinTool = defineTool({
	name: "checkin_under-pressure",
	description: "Record a field check-in for the Under Pressure pack after a session or match. One check-in per task per date. Tasks: no-hesitation, reviewed-goals, quiet-match.",
	parameters: Type.Object({
		task: Type.Union([Type.Literal("no-hesitation"), Type.Literal("reviewed-goals"), Type.Literal("quiet-match")]),
		date: Type.String({ description: "ISO date (YYYY-MM-DD) of the session or match" }),
		done: Type.Union([Type.Literal("yes"), Type.Literal("partly"), Type.Literal("no")]),
		notes: Type.Optional(Type.String()),
	}),
	execute: async (args, api, context) => {
		const keeperId = keeperIdOf({ conversationId: api.conversationId, agent: await api.agent(context) });
		const event = await api.commit((tx) => appendEvent(tx, keeperId, "field.checkin", { task: args.task, date: args.date, done: args.done, notes: args.notes ?? "" }, CTX), context);
		return { content: [{ type: "text", text: `recorded field.checkin ${args.task} ${args.date} ${args.done} (t=${event.t})` }] };
	},
});

